var ENGINE = _global.getCurrentEngine();
var INTERFACE = _global.getCurrentInterface();
var start_x = 320;
var start_y = 240;
var SHELL = _global.getCurrentShell();
var language;
var localized_frame = 1;
if(SHELL.getLocalizedFrame != undefined)
{
   localized_frame = SHELL.getLocalizedFrame();
}
switch(localized_frame)
{
   case 1:
      language = "english";
      break;
   case 2:
      language = "portuguese";
      break;
   case 3:
      language = "french";
      break;
   case 4:
      language = "spanish";
      break;
   default:
      language = "english";
}
background_mc.board_mc_states.gotoAndStop(language);
beans_btn_states.gotoAndStop(language);
background_mc.coffeebag_mc_states.gotoAndStop(language);
background_mc.wall.coffeeshop_mc_states.gotoAndStop(language);
background_mc.wall.exit_mc_states.gotoAndStop(language);
background_mc.town_btn_states.gotoAndStop(language);
triggers_mc.town_mc.triggerFunction = function()
{
   ENGINE.sendJoinRoom("town",290,260);
};
triggers_mc.book_mc.triggerFunction = function()
{
   ENGINE.sendJoinRoom("book",600,290);
};
triggers_mc.beans_mc.triggerFunction = function()
{
   ENGINE.sendJoinGame("beans",true);
};
background_mc.town_btn_states.town_btn.onRelease = function()
{
   ENGINE.sendPlayerMove(375,196);
};
background_mc.book_btn.onRelease = function()
{
   ENGINE.sendPlayerMove(640,395);
};
beans_btn_states.beans_btn.onRollOut = INTERFACE.closeHint;
beans_btn_states.beans_btn.onRollOver = function()
{
   INTERFACE.showHint(this,"beans_hint");
};
beans_btn_states.beans_btn.onRelease = function()
{
   ENGINE.sendPlayerMove(520,320);
};
triggers_mc._visible = false;
block_mc._visible = false;
